    private static function db(): PDO { return Database::connection(); }
    private static function input(): array { $raw=file_get_contents('php://input'); $data=json_decode($raw?:'{}',true); return is_array($data)?$data:[]; }
    private static function csvCell(mixed $value): string { $cell=(string)($value??''); return preg_match('/^[\x00-\x20]*[=+@-]/',$cell) ? "'".$cell : $cell; }
    private static function audit(?int $actor,string $action,string $type='',?int $id=null,string $outcome='success',array $meta=[]): void {
        $q=self::db()->prepare('INSERT INTO audit_logs(actor_user_id,action,record_type,record_id,outcome,metadata_json,ip_address) VALUES(?,?,?,?,?,?,?)');
        $q->execute([$actor,$action,$type,$id,$outcome,json_encode($meta,JSON_UNESCAPED_SLASHES),substr($_SERVER['REMOTE_ADDR']??'',0,45)]);
    }
    private static function notify(int $user,string $title,string $message,?string $type=null,?int $id=null): void { $q=self::db()->prepare('INSERT INTO notifications(user_id,title,message,record_type,record_id) VALUES(?,?,?,?,?)'); $q->execute([$user,$title,$message,$type,$id]); }
    private static function json(array $data,int $status=200): never { Http::respond($data,$status); }
    private static function positiveId(string $v): int { if (!ctype_digit($v)|| (int)$v<1) Http::fail(404,'Record not found.'); return (int)$v; }
    private static function validDate(string $value): bool { $date=\DateTimeImmutable::createFromFormat('!Y-m-d',$value); return $date!==false && $date->format('Y-m-d')===$value; }
    private static function ownsRequest(int $id,array $u): array {
        $q=self::db()->prepare('SELECT r.*,p.name pet_name,p.owner_id,p.species,p.breed,p.sex,p.birth_date,p.color,p.weight_kg,p.health_notes FROM relocation_requests r JOIN pets p ON p.id=r.pet_id WHERE r.id=?'); $q->execute([$id]); $row=$q->fetch();
        if (!$row || ($u['role']==='owner' && (int)$row['owner_id']!==$u['id']) || ($u['role']==='staff' && $row['assigned_staff_id']!==null && (int)$row['assigned_staff_id']!==$u['id'])) Http::fail(404,'Relocation request not found.');
        return $row;
    }
    private static function ownsPet(int $id,array $u): array {
        $q=self::db()->prepare('SELECT * FROM pets WHERE id=?');$q->execute([$id]);$pet=$q->fetch();
        if(!$pet||($u['role']==='owner'&&(int)$pet['owner_id']!==$u['id'])||!in_array($u['role'],['owner','admin'],true))Http::fail(404,'Pet profile not found.');
        return $pet;
    }
