        if($path==='/reports/stats'&&$method==='GET'){Auth::requireRole('admin');$status=$db->query('SELECT status,COUNT(*) total FROM relocation_requests GROUP BY status')->fetchAll();$monthly=$db->query("SELECT DATE_FORMAT(created_at,'%Y-%m') month,COUNT(*) total FROM relocation_requests WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 11 MONTH) GROUP BY month ORDER BY month")->fetchAll();$docs=$db->query('SELECT review_status,COUNT(*) total FROM uploaded_documents GROUP BY review_status')->fetchAll();$delayed=(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status NOT IN ('completed','cancelled') AND requested_date<CURDATE()")->fetchColumn();$summary=['requests'=>(int)$db->query('SELECT COUNT(*) FROM relocation_requests')->fetchColumn(),'completed'=>(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status='completed'")->fetchColumn(),'ongoing'=>(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status IN ('picked_up','in_transit','arrived','released')")->fetchColumn(),'pending'=>(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status IN ('request_submitted','request_confirmed','documents_pending','documents_under_review','corrections_required')")->fetchColumn(),'delayed'=>$delayed,'cancelled'=>(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status='cancelled'")->fetchColumn()];self::json(['summary'=>$summary,'statuses'=>$status,'monthly'=>$monthly,'documents'=>$docs]);}
        if($path==='/reports.csv'&&$method==='POST'){
            Auth::requireRole('admin');$clauses=[];$params=[];$validStatuses=['request_submitted','request_confirmed','documents_pending','documents_under_review','corrections_required','documents_verified','pickup_scheduled','picked_up','in_transit','arrived','released','completed','cancelled'];
            foreach(['from'=>'>=','to'=>'<='] as $key=>$operator){$value=(string)($_GET[$key]??'');if($value!==''){if(!self::validDate($value))Http::fail(422,'Invalid report date filter.');$clauses[]='r.requested_date'.$operator.'?';$params[]=$value;}}
            $status=(string)($_GET['status']??'');if($status!==''){if(!in_array($status,$validStatuses,true))Http::fail(422,'Invalid report status filter.');$clauses[]='r.status=?';$params[]=$status;}
            foreach(['origin'=>'origin_province','destination'=>'destination_province'] as $key=>$column){$value=substr(trim((string)($_GET[$key]??'')),0,120);if($value!==''){$clauses[]='r.'.$column.' LIKE ?';$params[]='%'.$value.'%';}}
            if(!empty($_GET['from'])&&!empty($_GET['to'])&&(string)$_GET['from']>(string)$_GET['to'])Http::fail(422,'The report start date must be before its end date.');
