    private static function requireAuth(?array $u): void {if(!$u)Http::fail(401,'Please sign in to continue.');}
    private static function dashboard(array $u): array {
        $db=self::db();$s=[];$recent=[];
        if($u['role']==='owner'){
            $q=$db->prepare('SELECT COUNT(*) FROM pets WHERE owner_id=?');$q->execute([$u['id']]);$s['pets']=(int)$q->fetchColumn();
            $q=$db->prepare('SELECT COUNT(*) FROM relocation_requests r JOIN pets p ON p.id=r.pet_id WHERE p.owner_id=?');$q->execute([$u['id']]);$s['requests']=(int)$q->fetchColumn();
            $q=$db->prepare("SELECT COUNT(*) FROM relocation_requests r JOIN pets p ON p.id=r.pet_id WHERE p.owner_id=? AND r.status IN ('corrections_required','documents_pending','request_submitted')");$q->execute([$u['id']]);$s['attention']=(int)$q->fetchColumn();
            $q=$db->prepare("SELECT COUNT(*) FROM uploaded_documents d JOIN pets p ON p.owner_id=d.owner_id JOIN relocation_requests r ON r.pet_id=p.id AND r.id=d.request_id WHERE p.owner_id=? AND d.review_status='pending'");$q->execute([$u['id']]);$s['documents_pending']=(int)$q->fetchColumn();
            $q=$db->prepare("SELECT COUNT(*) FROM uploaded_documents d JOIN pets p ON p.owner_id=d.owner_id JOIN relocation_requests r ON r.pet_id=p.id AND r.id=d.request_id WHERE p.owner_id=? AND d.review_status='corrections'");$q->execute([$u['id']]);$s['documents_corrections']=(int)$q->fetchColumn();
            $q=$db->prepare("SELECT COUNT(*) FROM pickup_dropoff_schedules s JOIN relocation_requests r ON r.id=s.request_id JOIN pets p ON p.id=r.pet_id WHERE p.owner_id=? AND s.pickup_at>=NOW() AND s.status IN ('scheduled','changed')");$q->execute([$u['id']]);$s['upcoming_pickups']=(int)$q->fetchColumn();
            $q=$db->prepare('SELECT COUNT(*) FROM notifications WHERE user_id=? AND read_at IS NULL');$q->execute([$u['id']]);$s['unread_notifications']=(int)$q->fetchColumn();
            $q=$db->prepare("SELECT COUNT(*) FROM uploaded_documents WHERE owner_id=? AND valid_until IS NOT NULL AND valid_until BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 30 DAY)");$q->execute([$u['id']]);$s['documents_expiring']=(int)$q->fetchColumn();
            $q=$db->prepare('SELECT r.*,p.name pet_name FROM relocation_requests r JOIN pets p ON p.id=r.pet_id WHERE p.owner_id=? ORDER BY r.created_at DESC LIMIT 6');$q->execute([$u['id']]);$recent=$q->fetchAll();
        } else {
            $staff=$u['role']==='staff';$scope=$staff?' AND r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL':'';
            if($staff){$q=$db->prepare('SELECT COUNT(*) FROM relocation_requests r WHERE r.assigned_staff_id=? OR r.assigned_staff_id IS NULL');$q->execute([$u['id']]);$s['requests']=(int)$q->fetchColumn();}
            else $s['requests']=(int)$db->query('SELECT COUNT(*) FROM relocation_requests')->fetchColumn();
            $scopeSql=$staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'';
            $s['documents_pending']=(int)$db->query("SELECT COUNT(*) FROM uploaded_documents d JOIN relocation_requests r ON r.id=d.request_id WHERE d.review_status='pending'".$scopeSql)->fetchColumn();
            $s['documents_corrections']=(int)$db->query("SELECT COUNT(*) FROM uploaded_documents d JOIN relocation_requests r ON r.id=d.request_id WHERE d.review_status='corrections'".$scopeSql)->fetchColumn();
            $s['ongoing']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests r WHERE r.status IN ('picked_up','in_transit','arrived','released')".($staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'').'')->fetchColumn();
            $s['delayed']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests r WHERE r.status NOT IN ('completed','cancelled') AND r.requested_date<CURDATE()".($staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'').'')->fetchColumn();
            $s['pending_requests']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests r WHERE r.status IN ('request_submitted','request_confirmed','documents_pending','documents_under_review','corrections_required')".($staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'').'')->fetchColumn();
            $s['completed']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests r WHERE r.status='completed'".($staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'').'')->fetchColumn();
            $s['upcoming_pickups']=(int)$db->query("SELECT COUNT(*) FROM pickup_dropoff_schedules s JOIN relocation_requests r ON r.id=s.request_id WHERE s.pickup_at>=NOW() AND s.status IN ('scheduled','changed')".($staff?' AND (r.assigned_staff_id='.(int)$u['id'].' OR r.assigned_staff_id IS NULL)':'').'')->fetchColumn();
            if($u['role']==='admin'){$s['active_users']=(int)$db->query('SELECT COUNT(*) FROM users WHERE active=1')->fetchColumn();$s['owners']=(int)$db->query("SELECT COUNT(*) FROM users WHERE role='owner' AND active=1")->fetchColumn();$s['staff']=(int)$db->query("SELECT COUNT(*) FROM users WHERE role='staff' AND active=1")->fetchColumn();$s['pets']=(int)$db->query('SELECT COUNT(*) FROM pets')->fetchColumn();$s['completed']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status='completed'")->fetchColumn();$s['pending_requests']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status IN ('request_submitted','request_confirmed','documents_pending','documents_under_review','corrections_required')")->fetchColumn();$s['delayed']=(int)$db->query("SELECT COUNT(*) FROM relocation_requests WHERE status NOT IN ('completed','cancelled') AND requested_date<CURDATE()")->fetchColumn();}
            if($staff){$q=$db->prepare('SELECT r.*,p.name pet_name FROM relocation_requests r JOIN pets p ON p.id=r.pet_id WHERE r.assigned_staff_id=? OR r.assigned_staff_id IS NULL ORDER BY r.updated_at DESC LIMIT 6');$q->execute([$u['id']]);$recent=$q->fetchAll();}
            else $recent=$db->query('SELECT r.*,p.name pet_name FROM relocation_requests r JOIN pets p ON p.id=r.pet_id ORDER BY r.updated_at DESC LIMIT 6')->fetchAll();
        }
        return ['stats'=>$s,'recent'=>$recent];
    }
